INSERT INTO `notification_templates` VALUES (1,'payment.success.email','payment.success','email','Order confirmed — {{order_number}}','<p>Hi {{customer_name}},</p><p>Thank you for your order with <strong>{{site_name}}</strong>. Your payment of <strong>₹{{amount}}</strong> is confirmed.</p>{{order_summary_html}}<p style=\"margin:16px 0 8px;\"><strong>Delivery</strong><br>{{delivery_address}}<br>{{delivery_slot_line}}</p>{{order_items_html}}<p style=\"margin:20px 0;\"><a href=\"{{track_order_url}}\" style=\"display:inline-block;background:#2d7048;color:#fff;padding:12px 20px;border-radius:6px;text-decoration:none;font-weight:600;\">Track order</a></p><p style=\"font-size:13px;color:#64748b;\">Payment via {{gateway_name}}. Reference: {{payment_reference}}</p>','Hi {{customer_name}}, order {{order_number}} is confirmed. Total Rs {{amount}}. {{order_items_text}} Delivery: {{delivery_address}} ({{delivery_slot_line}}). Track: {{track_order_url}}',NULL,NULL,NULL,1,'2026-11-10 12:50:32','2026-11-10 12:50:33'),(2,'payment.failed.email','payment.failed','email','Payment issue — order {{order_number}}','<p>Hi {{customer_name}},</p><p>Your payment for order <strong>{{order_number}}</strong> (₹{{amount}}) via {{gateway_name}} could not be completed.</p><p>You can try again securely:</p><p><a href=\"{{payment_retry_url}}\" style=\"display:inline-block;background:#2d7048;color:#fff;padding:12px 20px;border-radius:6px;text-decoration:none;font-weight:600;\">Retry payment</a></p><p style=\"font-size:13px;color:#64748b;\">Need help? View <a href=\"{{order_url}}\">order details</a>.</p>','Payment for order {{order_number}} (Rs {{amount}}) failed. Retry: {{payment_retry_url}}',NULL,NULL,NULL,1,'2026-11-10 12:50:32','2026-11-10 12:50:33'),(3,'support.ticket_created.email','support.ticket_created','email','Support ticket {{ticket_number}} received','<p>Hi {{customer_name}},</p><p>We received your support request ({{ticket_number}}). Our team will respond soon.</p>','We received your support ticket {{ticket_number}}.',NULL,NULL,NULL,1,'2026-11-10 12:50:32',NULL),(4,'support.ticket_replied.email','support.ticket_replied','email','Update on ticket {{ticket_number}}','<p>Hi {{customer_name}},</p><p>There is a new reply on your support ticket {{ticket_number}}.</p>','New reply on support ticket {{ticket_number}}.',NULL,NULL,NULL,1,'2026-11-10 12:50:32',NULL),(5,'support.ticket_created.in_app','support.ticket_created','in_app',NULL,NULL,NULL,NULL,'Support ticket opened','Ticket {{ticket_number}} was created.',1,'2026-11-10 12:50:32',NULL),(6,'refund.status_updated.email','refund.status_updated','email','Refund update — {{request_number}}','<p>Hi {{customer_name}},</p><p>Your refund request <strong>{{request_number}}</strong> for order <strong>{{order_number}}</strong> status is now: <strong>{{status_label}}</strong>.</p>','Refund {{request_number}} (order {{order_number}}) status: {{status_label}}.',NULL,NULL,NULL,1,'2026-11-10 12:50:32','2026-11-10 12:50:33'),(7,'order.placed.email','order.placed','email','Order {{order_number}} — complete payment','<p>Hi {{customer_name}},</p><p>Thank you for shopping with {{site_name}}. Your order <strong>{{order_number}}</strong> is placed and awaiting payment of <strong>₹{{amount}}</strong>.</p><p>Complete payment securely via {{gateway_name}}:</p><p><a href=\"{{payment_retry_url}}\" style=\"display:inline-block;background:#2d7048;color:#fff;padding:12px 20px;border-radius:6px;text-decoration:none;font-weight:600;\">Pay now</a></p><p style=\"font-size:13px;color:#64748b;\">You can also view your order anytime from <a href=\"{{order_url}}\">order details</a>.</p>','Hi {{customer_name}}, order {{order_number}} (Rs {{amount}}) is awaiting payment. Pay at {{payment_retry_url}} or view {{order_url}}.',NULL,NULL,NULL,1,'2026-11-10 12:50:33',NULL),(8,'order.status.email','order.status','email','Order {{order_number}} — {{status_label}}','<p>Hi {{customer_name}},</p><p>Your order <strong>{{order_number}}</strong> is now: <strong>{{status_label}}</strong>.</p><p>Amount: ₹{{amount}}</p><p><a href=\"{{order_url}}\" style=\"display:inline-block;background:#2d7048;color:#fff;padding:12px 20px;border-radius:6px;text-decoration:none;font-weight:600;\">View order</a></p>','Order {{order_number}} status: {{status_label}}. View: {{order_url}}',NULL,NULL,NULL,1,'2026-11-10 12:50:33',NULL),(9,'refund.initiated.email','refund.initiated','email','Refund initiated — {{request_number}}','<p>Hi {{customer_name}},</p><p>We have initiated your refund <strong>{{request_number}}</strong> for order <strong>{{order_number}}</strong>{{amount_line}}.</p><p>Status: {{status_label}}</p><p style=\"font-size:13px;color:#64748b;\">Refunds typically appear in your account within 5–7 business days depending on your bank.</p>','Refund {{request_number}} for order {{order_number}} has been initiated. Status: {{status_label}}.',NULL,NULL,NULL,1,'2026-11-10 12:50:33',NULL),(10,'refund.completed.email','refund.completed','email','Your Veggie Tokri refund has been processed – Order #{{order_number}}','<p>Hi {{customer_name}},</p><p>Your refund of <strong>{{amount_line}}</strong> for order <strong>{{order_number}}</strong> has been processed by {{gateway_name}}.</p><p>Refund reference: <strong>{{refund_reference}}</strong><br>Completed: {{completion_date}}</p><p><a href=\"{{order_url}}\" style=\"display:inline-block;background:#2d7048;color:#fff;padding:12px 20px;border-radius:6px;text-decoration:none;font-weight:600;\">View order</a></p><p style=\"font-size:13px;color:#64748b;\">Bank posting times vary by issuer; we do not control settlement speed.</p>','Hi {{customer_name}}, refund {{amount_line}} for order {{order_number}} is complete ({{gateway_name}}). Reference: {{refund_reference}}. View: {{order_url}}',NULL,NULL,NULL,1,'2026-11-10 12:50:33','2026-11-10 12:50:33'),(15,'order.payment_timeout_cancelled.email','order.payment_timeout_cancelled','email','Order {{order_number}} cancelled — payment not received','<p>Hi {{customer_name}},</p><p>Your order <strong>{{order_number}}</strong> was cancelled because payment was not completed within the allowed time.</p><p>{{cancellation_reason}}</p><p>Amount: ₹{{amount}}</p><p>If you still want these items, you can place a new order anytime.</p><p><a href=\"{{order_url}}\" style=\"display:inline-block;background:#2d7048;color:#fff;padding:12px 20px;border-radius:6px;text-decoration:none;font-weight:600;\">View order</a></p>','Order {{order_number}} was cancelled: payment was not completed in time. {{cancellation_reason}} View: {{order_url}}',NULL,NULL,NULL,1,'2026-11-10 12:50:34',NULL);
